// This ensures full coverage across the same country set as the US map data.
allCountryCodes.forEach(countryCode => {
  if (!visaRequirements.AD[countryCode]) {
    visaRequirements.AD[countryCode] = VISA_TYPES.VISA_FREE;
  }
});

